slides=[];t=0
for i,(title,mins,message,visual,notes) in enumerate(cards,1):
    asset=visual[1:] if visual.startswith('@') else f'running_example/{visual}.png' if visual else ''
    slides.append(dict(slide=i,title=title,minutes=mins,start=t,end=t+mins,message=message,speaker_notes=notes,asset=asset,status='Live demonstration' if title.startswith('LIVE DEMO') else 'Foundation' if i<=11 else 'Existing evidence / selected visuals pending'))
