assert sum(s['minutes'] for s in slides[:11])==22
(OUT/'storyboard_45min.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),encoding='utf8')
intro='45-MINUTE SEMINAR STORYBOARD — revised 14 November 2026\n\n22 minutes: context, 2D foundation and computation.\n23 minutes: rover execution, collision avoidance, policy selection, lookahead, multi-rover allocation, timing and synthesis.\nOne configurable running example supports the foundation; later work uses its own recorded evidence.\nThis is a working storyboard, not a finished slide deck.\n\n'
intro+='LIVE DEMO: minutes 11–17, pinned 55-object scene, one target push.\nSee live_demo/DEMO_RUNBOOK.html and Start seminar demo.cmd.\n\n'
(OUT/'SEMINAR_STORY_45_MIN.txt').write_text(intro+'\n\n'.join(f"{s['slide']:02d}. {s['title']} ({s['start']}–{s['end']} min)\n{s['message']}\nVISUAL: {s['asset'] or 'Diagram / evidence placeholder'}\n{s['speaker_notes']}" for s in slides),encoding='utf8')
esc=html.escape
body=''
