walk='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>One running example</title><style>body{font:18px system-ui;background:#f0f4f6;color:#183447;max-width:1000px;margin:20px auto;padding:0 16px}img{width:100%;max-height:78vh;object-fit:contain}button,select{font:inherit;padding:8px;margin:5px}small{display:block;margin:12px}</style><h1>One scene, step by step</h1><button id="prev">← Previous</button><select id="stage" aria-label="Stage"></select><button id="next">Next →</button><img id="picture" alt="Current planner visualization"><small>Generated from current planner code. Heat scale and coordinates are fixed across before/after views. Spillage is a separate estimate; the staging transition uses no spillage. Arrow keys change stages.</small><script>const stages='''+json.dumps(stages)+''';const s=document.getElementById('stage'); stages.forEach((v,i)=>s.add(new Option((i+1)+'. '+v[1],i)));function show(i){s.selectedIndex=Math.max(0,Math.min(stages.length-1,i));document.getElementById('picture').src=stages[s.selectedIndex][0]+'.png';document.getElementById('picture').alt=stages[s.selectedIndex][1];}s.onchange=()=>show(s.selectedIndex);document.getElementById('prev').onclick=()=>show(s.selectedIndex-1);document.getElementById('next').onclick=()=>show(s.selectedIndex+1);document.onkeydown=e=>{if(e.key==='ArrowRight')show(s.selectedIndex+1);if(e.key==='ArrowLeft')show(s.selectedIndex-1)};show(0);</script></html>'''
(OUT/'running_example/example_walkthrough.html').write_text(walk,encoding='utf8')
